import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const easeOutClass = "ease-[cubic-bezier(0.23,1,0.32,1)]";

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

export function edgeOffset(placement: string | null, distance: number) {
  switch (placement) {
    case "top":
      return { x: 0, y: distance };
    case "left":
      return { x: distance, y: 0 };
    case "right":
      return { x: -distance, y: 0 };
    default:
      return { x: 0, y: -distance };
  }
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

export const fieldLabelStyles = "text-sm font-medium text-foreground";
export const fieldDescriptionStyles = "text-xs leading-5 text-muted-foreground";
export const fieldErrorStyles = "text-xs leading-5 text-destructive";

export const fieldInputStyles =
  "min-h-12 w-full cursor-text rounded-lg border border-input bg-card text-base text-foreground shadow-[var(--shadow-card)] outline-none transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] placeholder:text-muted-foreground/80 hover:border-primary/45 focus:border-ring focus:ring-3 focus:ring-ring/50 invalid:border-destructive invalid:ring-3 invalid:ring-destructive/20 invalid:hover:border-destructive invalid:focus:border-destructive invalid:focus:ring-destructive/30 [&[readonly]]:bg-muted/40 [&[readonly]]:hover:border-input disabled:cursor-not-allowed disabled:bg-muted disabled:opacity-60 disabled:hover:border-input sm:text-sm";

export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:border-primary/45 focus-within:border-ring focus-within:hover:border-ring focus-within:ring-3 focus-within:ring-ring/50 group-invalid:border-destructive group-invalid:ring-3 group-invalid:ring-destructive/20 group-invalid:hover:border-destructive group-invalid:focus-within:border-destructive group-invalid:focus-within:hover:border-destructive group-invalid:focus-within:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-disabled:bg-muted group-disabled:opacity-60 group-disabled:hover:border-input";

export const fieldTriggerStyles =
  "grid size-11 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none transition-[color,background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring disabled:cursor-default disabled:opacity-50";

"use client";

import { CheckIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import {
  ListBox as AriaListBox,
  ListBoxItem as AriaListBoxItem,
  composeRenderProps,
  type ListBoxItemProps,
  type ListBoxProps,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";

export function ListBox<T extends object>({
  className,
  ...props
}: ListBoxProps<T>) {
  return (
    <AriaListBox
      {...props}
      data-slot="list-box"
      className={composeRenderProps(className, (className) =>
        cn(
          "grid max-h-72 w-full gap-1 overflow-y-auto rounded-lg border border-border bg-card p-1.5 shadow-[var(--shadow-card)] outline-none",
          className,
        ),
      )}
    />
  );
}

export function ListBoxItem({
  className,
  children,
  ...props
}: ListBoxItemProps) {
  return (
    <AriaListBoxItem
      {...props}
      data-slot="list-box-item"
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-3 text-sm text-foreground outline-none hover:bg-muted focus:bg-muted selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50 focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ring",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {content}
          <SelectionMark isSelected={isSelected} />
        </>
      ))}
    </AriaListBoxItem>
  );
}

export function SelectionMark({
  isSelected,
  className,
}: {
  isSelected: boolean;
  className?: string;
}) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.span
      aria-hidden="true"
      className={cn("ms-auto shrink-0", className)}
      initial={false}
      animate={{ opacity: isSelected ? 1 : 0, scale: isSelected ? 1 : 0.85 }}
      transition={{ duration: reduceMotion ? 0 : duration.fast, ease: easeOut }}
    >
      <CheckIcon size={16} weight="bold" />
    </motion.span>
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  Popover as AriaPopover,
  composeRenderProps,
  type PopoverProps,
} from "react-aria-components";
import { easeOut, edgeOffset } from "./motion";
import { cn } from "./utils";

type StyledPopoverProps = PopoverProps & { "data-slot"?: string };

export function Popover({
  className,
  "data-slot": dataSlot = "popover",
  ...props
}: StyledPopoverProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      render={
        props.render ??
        ((domProps, { placement, isExiting }) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            initial={
              reduceMotion || props.shouldSkipAnimation
                ? false
                : { opacity: 0, ...edgeOffset(placement, 5), scale: 0.98 }
            }
            animate={
              isExiting
                ? {
                    opacity: 0,
                    ...(reduceMotion ? {} : edgeOffset(placement, 5)),
                    scale: reduceMotion ? 1 : 0.99,
                  }
                : { opacity: 1, x: 0, y: 0, scale: 1 }
            }
            transition={{
              duration: reduceMotion ? 0 : isExiting ? 0.14 : 0.2,
              ease: easeOut,
            }}
          />
        ))
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "max-w-[calc(100vw-2rem)] overflow-auto overscroll-contain rounded-xl border border-border bg-popover p-5 text-popover-foreground shadow-[var(--shadow-float)] outline-none data-[placement=top]:origin-bottom data-[placement=bottom]:origin-top data-[placement=left]:origin-right data-[placement=right]:origin-left",
          className,
        ),
      )}
    />
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { Button, type ButtonProps } from "react-aria-components";

export function PressButton({ isDisabled, ...props }: ButtonProps) {
  const reduceMotion = useReducedMotion();

  return (
    <Button
      data-slot="press-button"
      {...props}
      isDisabled={isDisabled}
      render={
        props.render ??
        ((domProps) => (
          <motion.button
            {...(domProps as HTMLMotionProps<"button">)}
            whileTap={reduceMotion || isDisabled ? undefined : { scale: 0.96 }}
            transition={{ type: "spring", stiffness: 500, damping: 36 }}
          />
        ))
      }
    />
  );
}

"use client";

import { XIcon } from "@phosphor-icons/react";
import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  Tag as AriaTag,
  TagGroup as AriaTagGroup,
  type TagGroupProps as AriaTagGroupProps,
  composeRenderProps,
  Label,
  TagList,
  type TagProps,
} from "react-aria-components";
import { cn } from "./utils";
import { PressButton } from "./press-button";

export function TagGroup({ className, ...props }: AriaTagGroupProps) {
  return (
    <AriaTagGroup
      {...props}
      data-slot="tag-group"
      className={cn("grid gap-2", className)}
    />
  );
}

export function TagGroupLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="tag-group-label"
      className={cn("text-sm font-medium", className)}
    />
  );
}

export function TagListView<T extends object>({
  className,
  ...props
}: React.ComponentProps<typeof TagList<T>>) {
  return (
    <TagList
      {...props}
      data-slot="tag-list"
      className={composeRenderProps(className, (className) =>
        cn("flex flex-wrap gap-2.5", className),
      )}
    />
  );
}

export function Tag({ className, children, ...props }: TagProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaTag
      {...props}
      data-slot="tag"
      render={
        props.render ??
        ((domProps, { isPressed, isDisabled }) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            initial={false}
            animate={{ scale: isPressed && !isDisabled ? 0.96 : 1 }}
            transition={
              reduceMotion
                ? { duration: 0 }
                : { type: "spring", stiffness: 500, damping: 36 }
            }
          />
        ))
      }
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "flex min-h-11 cursor-pointer items-center gap-1 rounded-lg bg-card ps-3 pe-1 text-sm font-medium shadow-[var(--shadow-card)] ring-1 ring-border/80 hover:bg-muted selected:bg-accent selected:text-accent-foreground selected:ring-primary/35 disabled:cursor-default disabled:opacity-50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
          className,
        ),
      )}
    >
      {(state) => (
        <>
          <span className={state.allowsRemoving ? "pe-1" : "pe-2"}>
            {typeof children === "function" ? children(state) : children}
          </span>
          {state.allowsRemoving && (
            <PressButton
              slot="remove"
              data-slot="tag-remove"
              aria-label={`Remove ${props.textValue ?? (typeof children === "string" ? children : "tag")}`}
              className="grid size-11 cursor-pointer place-items-center rounded-md text-muted-foreground hover:bg-card hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"
            >
              <XIcon size={14} weight="bold" aria-hidden="true" />
            </PressButton>
          )}
        </>
      )}
    </AriaTag>
  );
}

"use client";

import { CaretDownIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import { type ReactNode, useContext } from "react";
import {
  Button as AriaButton,
  ComboBox as AriaComboBox,
  type ComboBoxProps as AriaComboBoxProps,
  ComboBoxValue as AriaComboBoxValue,
  ComboBoxStateContext,
  composeRenderProps,
  FieldError,
  Input,
  Label,
  ListBox,
  ListBoxItem,
  Text,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldInputStyles,
  fieldLabelStyles,
  fieldTriggerStyles,
} from "./field-styles";
import { SelectionMark } from "./list-box";
import { Popover } from "./popover";
import { Tag, TagGroup, TagListView } from "./tag-group";

const comboBoxPopoverStyles =
  "w-[var(--trigger-width)] rounded-lg border-0 p-1.5 ring-1 ring-border/70";
const comboBoxItemStyles =
  "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-2.5 py-2 text-sm outline-none hover:bg-muted focus:bg-muted focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-ring selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50";

export interface ComboBoxOption {
  id: string;
  name: string;
  description?: string;
}

type ComboBoxBaseProps<M extends "single" | "multiple"> = Omit<
  AriaComboBoxProps<ComboBoxOption, M>,
  "children" | "className"
> & {
  label?: string;
  description?: string;
  options?: ComboBoxOption[];
  placeholder?: string;
  className?: AriaComboBoxProps<ComboBoxOption, M>["className"];
  children?: AriaComboBoxProps<ComboBoxOption, M>["children"];
};

export interface ComboBoxProps extends ComboBoxBaseProps<"single"> {
  selectionMode?: "single";
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export interface MultiSelectComboBoxProps
  extends ComboBoxBaseProps<"multiple"> {
  selectionMode: "multiple";
}

export function ComboBox(props: ComboBoxProps): React.ReactElement;
export function ComboBox(props: MultiSelectComboBoxProps): React.ReactElement;
export function ComboBox(props: ComboBoxProps | MultiSelectComboBoxProps) {
  if (props.selectionMode === "multiple") {
    return <MultipleComboBox {...props} />;
  }
  return <SingleComboBox {...props} />;
}

function SingleComboBox({
  label,
  description,
  options,
  placeholder = "Search options",
  className,
  children,
  value,
  defaultValue,
  onValueChange,
  ...props
}: ComboBoxProps) {
  return (
    <AriaComboBox
      {...props}
      data-slot="combo-box"
      selectedKey={value ?? props.selectedKey}
      defaultSelectedKey={defaultValue ?? props.defaultSelectedKey}
      onSelectionChange={(key) => {
        props.onSelectionChange?.(key);
        onValueChange?.(key === null ? "" : String(key));
      }}
      className={composeRenderProps(className, (className) =>
        cn("group flex w-full flex-col gap-2", className),
      )}
    >
      {children ?? (
        <ComboBoxDefaults
          label={label}
          description={description}
          options={options}
          placeholder={placeholder}
        />
      )}
    </AriaComboBox>
  );
}

function MultipleComboBox({
  label,
  description,
  options,
  placeholder = "Search options",
  className,
  children,
  ...props
}: MultiSelectComboBoxProps) {
  return (
    <AriaComboBox
      {...props}
      data-slot="combo-box"
      className={composeRenderProps(className, (className) =>
        cn("group flex w-full flex-col gap-2", className),
      )}
    >
      {children ?? (
        <ComboBoxDefaults
          label={label}
          description={description}
          options={options}
          placeholder={placeholder}
          multiple
        />
      )}
    </AriaComboBox>
  );
}

function ComboBoxDefaults({
  label,
  description,
  options,
  placeholder,
  multiple = false,
}: {
  label?: string;
  description?: string;
  options?: ComboBoxOption[];
  placeholder: string;
  multiple?: boolean;
}) {
  return (
    <>
      {label && <ComboBoxLabel>{label}</ComboBoxLabel>}
      <div className="relative flex items-center">
        <ComboBoxInput placeholder={placeholder} />
        <ComboBoxTrigger />
      </div>
      {multiple && <ComboBoxTags />}
      {description && <ComboBoxDescription>{description}</ComboBoxDescription>}
      <ComboBoxError />
      <Popover
        data-slot="combo-box-content"
        placement="bottom start"
        offset={7}
        maxHeight={268}
        className={comboBoxPopoverStyles}
      >
        <ListBox
          data-slot="combo-box-list-box"
          items={options ?? []}
          renderEmptyState={() => (
            <div className="px-3 py-3 text-sm text-muted-foreground">
              No matching options.
            </div>
          )}
          className="grid gap-1 outline-none"
        >
          {(option) => (
            <ListBoxItem
              data-slot="combo-box-item"
              id={option.id}
              textValue={option.name}
              className={comboBoxItemStyles}
            >
              {({ isSelected }) => (
                <>
                  <span className="min-w-0">
                    <span className="block font-medium">{option.name}</span>
                    {option.description && (
                      <span className="mt-0.5 block text-xs text-muted-foreground group-selected/item:text-accent-foreground">
                        {option.description}
                      </span>
                    )}
                  </span>
                  <SelectionMark isSelected={isSelected} />
                </>
              )}
            </ListBoxItem>
          )}
        </ListBox>
      </Popover>
    </>
  );
}

export function ComboBoxTags({
  className,
  label = "Selected options",
  emptyText = "No options selected.",
}: {
  className?: string;
  label?: string;
  emptyText?: string;
}) {
  return (
    <AriaComboBoxValue<ComboBoxOption>
      data-slot="combo-box-tags"
      className={cn("min-w-0", className)}
    >
      {({ state }) => (
        <TagGroup
          aria-label={label}
          onRemove={(keys) => {
            if (Array.isArray(state.value)) {
              state.setValue(state.value.filter((key) => !keys.has(key)));
            }
          }}
        >
          <TagListView
            items={state.selectedItems.map((item) => ({
              id: item.key,
              name: item.textValue,
            }))}
            renderEmptyState={() => (
              <span className="text-sm text-muted-foreground">{emptyText}</span>
            )}
          >
            {(item) => (
              <Tag id={item.id} textValue={item.name}>
                {item.name}
              </Tag>
            )}
          </TagListView>
        </TagGroup>
      )}
    </AriaComboBoxValue>
  );
}

export function ComboBoxLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="combo-box-label"
      className={cn(fieldLabelStyles, className)}
    />
  );
}

export function ComboBoxInput({
  className,
  ...props
}: React.ComponentProps<typeof Input>) {
  return (
    <Input
      {...props}
      data-slot="combo-box-input"
      className={composeRenderProps(className, (className) =>
        cn(fieldInputStyles, "ps-3.5 pe-12", className),
      )}
    />
  );
}

export function ComboBoxTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AriaButton>) {
  return (
    <AriaButton
      {...props}
      data-slot="combo-box-trigger"
      aria-label={props["aria-label"] ?? "Show options"}
      className={composeRenderProps(className, (className) =>
        cn(fieldTriggerStyles, "absolute inset-y-0 end-1 my-auto", className),
      )}
    >
      {children ?? <ComboBoxChevron />}
    </AriaButton>
  );
}

function ComboBoxChevron() {
  const isOpen = useContext(ComboBoxStateContext)?.isOpen;
  const reduceMotion = useReducedMotion();
  return (
    <motion.span
      aria-hidden="true"
      initial={false}
      animate={{ rotate: isOpen ? 180 : 0 }}
      transition={{ duration: reduceMotion ? 0 : duration.base, ease: easeOut }}
    >
      <CaretDownIcon size={16} />
    </motion.span>
  );
}

export function ComboBoxContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Popover>) {
  return (
    <Popover
      {...props}
      data-slot="combo-box-content"
      placement={props.placement ?? "bottom start"}
      offset={props.offset ?? 7}
      maxHeight={props.maxHeight ?? 268}
      className={composeRenderProps(className, (className) =>
        cn(comboBoxPopoverStyles, className),
      )}
    >
      <ListBox
        data-slot="combo-box-list-box"
        className="grid gap-1 outline-none"
        renderEmptyState={() => (
          <div className="px-3 py-3 text-sm text-muted-foreground">
            No matching options.
          </div>
        )}
      >
        {children}
      </ListBox>
    </Popover>
  );
}

export function ComboBoxItem({
  className,
  children,
  ...props
}: Omit<React.ComponentProps<typeof ListBoxItem>, "children"> & {
  children: ReactNode;
}) {
  return (
    <ListBoxItem
      {...props}
      data-slot="combo-box-item"
      className={composeRenderProps(className, (className) =>
        cn(comboBoxItemStyles, className),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {content}
          <SelectionMark isSelected={isSelected} />
        </>
      ))}
    </ListBoxItem>
  );
}

export function ComboBoxDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="combo-box-description"
      className={cn(fieldDescriptionStyles, className)}
    />
  );
}

export function ComboBoxError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="combo-box-error"
      className={cn(fieldErrorStyles, className)}
    />
  );
}
